# Hypothesis: a decorator typed with Concatenate[int, P] should remove the injected leading argument from the wrapped signature, and a plain ParamSpec decorator should keep defaults and keyword-only parameters.
from typing import Callable, Concatenate, assert_type, reveal_type


def with_request_id[**P, R](fn: Callable[Concatenate[int, P], R]) -> Callable[P, R]:
    def wrapper(*args: P.args, **kwargs: P.kwargs) -> R:
        return fn(42, *args, **kwargs)
    return wrapper


def preserve[**P, R](fn: Callable[P, R]) -> Callable[P, R]:
    def wrapper(*args: P.args, **kwargs: P.kwargs) -> R:
        return fn(*args, **kwargs)
    return wrapper


@with_request_id
def handle(req: int, name: str, *, loud: bool = False) -> str:
    text = f'{req}:{name}'
    return text.upper() if loud else text


@preserve
def add(a: int, b: int = 10) -> int:
    return a + b


reveal_type(handle)
assert_type(handle('bob'), str)
assert handle('bob') == '42:bob'
assert handle('amy', loud=True) == '42:AMY'
assert_type(add(1), int)
assert add(1) == 11
assert add(1, b=2) == 3

handle('bob', loud='yes')  # expect-error

try:
    handle(7, 'x')  # expect-error
except TypeError:
    bad_call_rejected = True
else:
    bad_call_rejected = False
assert bad_call_rejected
